import type { LessonExpansion } from '../types.ts';
import {chapter,reasoning,coding,cpp} from './basics-helpers.ts';
export const bronzeExpansions: Record<string, LessonExpansion> = {
'pensar-en-algoritmos':chapter('pensar-en-algoritmos',[
 ['Separa la historia de las cantidades',"Cada paquete necesita dos lápices y un cuaderno. Para calcular cuántos puedes preparar, basta conocer las existencias y el consumo por paquete. El nombre de la escuela o el color de la mochila no afectan la cuenta salvo que el enunciado les asigne una regla. Escribe las unidades de cada variable para distinguir lápices, cuadernos y paquetes."],
 ['Encuentra un límite que toda respuesta respete',"Con once lápices puedes preparar como máximo cinco paquetes; con tres cuadernos, como máximo tres. Toda respuesta debe respetar ambos límites, así que no puede superar tres. Ese número sí se alcanza: tres paquetes consumen seis lápices y tres cuadernos. La cota superior demuestra que no hay una respuesta mayor y la construcción muestra que la cota es posible."],
 ['Del razonamiento al pseudocódigo',"El procedimiento es leer ambas cantidades, calcular lápices / 2, compararlo con cuadernos y escribir el menor. La división entera cuenta grupos completos, así que no necesitas armar paquetes uno por uno. Después de justificar estas operaciones, elige tipos y sintaxis. En otros problemas, simular puede servir como primer modelo antes de encontrar una cuenta equivalente."],
 ['Revisa la generalización',"Prueba cero lápices, cero cuadernos, cantidades que se agotan juntas y un recurso que sobra mucho. La misma fórmula debe cubrirlos. Si cambias la receta a tres lápices y dos cuadernos, compara lápices / 3 con cuadernos / 2. Los divisores vienen del consumo por paquete, no de los números del primer ejemplo."]
 ],[reasoning('limites','Construcción y cota','Hay 17 lápices y 6 cuadernos; cada paquete usa 3 lápices y 2 cuadernos. Calcula el máximo y explica por separado por qué no puede ser mayor y por qué sí se puede alcanzar.',['Calcula cuántos paquetes permite cada recurso.','El menor límite debe poder construirse.'],"Diecisiete lápices permiten cinco paquetes y seis cuadernos permiten tres. Ninguna respuesta puede superar tres porque faltaría un cuarto par de cuadernos. Tres sí se construyen con nueve lápices y seis cuadernos. La cota y la construcción coinciden, por lo que tres es el máximo."),coding('paquetes','Paquetes del taller',"Entrada: l y c (0 ≤ l,c ≤ 1000000000), lápices y cuadernos. Cada paquete lleva 2 lápices y 1 cuaderno.\n\nSalida: máximo número de paquetes completos.",['Los lápices permiten l / 2 paquetes.','Los cuadernos permiten c; toma el menor.'],'Cada paquete exige ambos recursos. Por ello la respuesta no supera l / 2 ni c. El menor de esos dos valores puede construirse porque no requiere más de lo disponible de ninguno. Ese argumento demuestra el óptimo para cualquier entrada, incluidos recursos en cero. El programa usa división entera, una comparación y salida: tiempo y memoria O(1).',cpp('    long long l,c; cin >> l >> c;\n    long long paquetes=l/2;\n    if(c<paquetes) paquetes=c;\n    cout << paquetes << "\\n";'),[['11 3\n','3\n'],['0 8\n','0\n'],['8 100\n','4\n'],['10 5\n','5\n']])]),
'complejidad':chapter('complejidad',[
 ['El tamaño de entrada es una variable',"Usamos n para representar un tamaño, como el número de estudiantes. Una prueba con n = 10 no indica por sí sola qué pasará con n = 100000. La complejidad describe cómo aumenta el trabajo al crecer n. No predice segundos exactos, que dependen del equipo y las operaciones, pero permite comparar enfoques antes de programarlos."],
 ['Suma recorridos, multiplica repeticiones anidadas',"Dos recorridos consecutivos de n elementos realizan aproximadamente 2n pasos: su costo es O(n). Si cada vuelta del primero ejecuta otro recorrido de n, hay aproximadamente n² pasos. Para parejas i < j se suman (n − 1) + ... + 1 = n(n − 1)/2; sigue siendo O(n²), aunque se evite contar cada pareja dos veces."],
 ['Un cálculo con números concretos',"Para n = 1000 hay 499500 parejas distintas. Para n = 100000 hay 4999950000. Multiplicar el tamaño por cien multiplica aproximadamente por diez mil el número de parejas. Esa cuenta permite detectar cuándo deja de ser viable enumerarlas. Una estimación de operaciones por segundo es orientativa; también importan el tipo de operación y el margen disponible."],
 ['Memoria y respuesta también tienen tamaño',"Guardar n enteros de 64 bits usa aproximadamente 8n bytes para sus valores, más el contenedor. Una tabla n × n crece mucho más. También considera la salida: contar parejas admite una fórmula, pero imprimirlas todas exige producir O(n²) resultados. Antes de optimizar, distingue el trabajo necesario por lo solicitado del que añadió tu implementación."]
 ],[reasoning('crecimiento','Compara dos recorridos','Para n = 1000, estima cuántas veces se ejecuta una instrucción en dos ciclos consecutivos de n vueltas y en dos ciclos anidados de n vueltas. Repite para n = 2000 y compara el factor de crecimiento.',['Suma cuando los ciclos son consecutivos.','Multiplica cuando cada vuelta exterior repite todo el interior.'],"Los recorridos consecutivos hacen 2000 y 4000 ejecuciones para los dos tamaños: el trabajo se duplica. Los anidados hacen 1000000 y 4000000: se cuadruplica. En el primer caso sumas las vueltas; en el segundo, cada vuelta exterior repite todas las interiores. Ambos códigos pueden tener dos for y costos distintos."),coding('parejas','Cuenta sin enumerar',"Entrada: n (1 ≤ n ≤ 1000000000), número de participantes.\n\nSalida: número de parejas de participantes distintos, sin importar el orden. El resultado cabe en long long.",['Cada participante puede acompañarse de n − 1 personas.','Ese conteo incluye cada pareja dos veces.'],'Hay n(n − 1) elecciones ordenadas: primera y segunda persona. Cada pareja no ordenada aparece como (A,B) y (B,A), así que dividimos entre dos. El producto máximo es menor que 10 elevado a 18 y cabe en long long. Con n = 1 no existe ninguna pareja. La fórmula usa O(1) tiempo y memoria, mientras enumerar parejas costaría O(n²).',cpp('    long long n; cin >> n;\n    cout << n*(n-1)/2 << "\\n";'),[['4\n','6\n'],['1\n','0\n'],['1000000000\n','499999999500000000\n']])]),
'ordenamiento':chapter('ordenamiento',[
 ['Ordenar crea relaciones entre vecinos',"Ordenar [8,2,5,2] produce [2,2,5,8]. Conserva las apariciones y cambia sus posiciones para que ningún valor supere al siguiente. Así quedan juntos los iguales y visibles los extremos. Esa relación entre vecinos permite resolver tareas que, sobre la lista original, exigirían buscar o comparar repetidamente."],
 ['Qué hace sort y qué no conserva',"sort(a.begin(), a.end()) ordena el vector según < en O(n log n) comparaciones. Si después necesitas posiciones originales, guarda cada valor con su índice antes de ordenar. Los índices nuevos describen el orden resultante. sort tampoco garantiza conservar el orden relativo de elementos iguales; si importa, define el desempate o usa una estrategia adecuada."],
 ['La posición k tiene una convención',"El tercer valor más pequeño está en índice dos porque el enunciado cuenta desde uno y el vector desde cero. En general, convierte k en k − 1. Para [2,2,5,8], el segundo valor sigue siendo dos: cuentas apariciones. Eliminar duplicados solo corresponde cuando se solicitan valores distintos."],
 ['Un empate con información original',"Ana tarda doce, Beto ocho y Carla doce. Los pares (tiempo, índice) son (12,0), (8,1), (12,2). Ordenados quedan (8,1), (12,0), (12,2), por lo que puedes recuperar a quién pertenece cada tiempo. Si solo piden el valor del k-ésimo tiempo, no necesitas esos índices. Guarda la información que exigirá la respuesta."],
 ['Cuándo ordenar es más trabajo del necesario',"Para encontrar únicamente el mínimo basta recorrer una vez: O(n). Ordenar cuesta O(n log n), pero puede servir si después harás varias consultas sobre posiciones por tamaño. Explica qué propiedad del orden usas y suma todos los costos, incluida cualquier copia o dato auxiliar para recuperar la información original."]
 ],[reasoning('repetidos','Orden y posiciones','Ordena [7,3,7,1,3]. Indica el cuarto elemento más pequeño contando repeticiones y el segundo valor distinto. Explica por qué son preguntas diferentes.',['Conserva las cinco apariciones al ordenar.','Eliminar duplicados cambia la cantidad de posiciones.'],'La lista ordenada es [1,3,3,7,7]. El cuarto elemento es 7. Los valores distintos son [1,3,7], cuyo segundo es 3. La lista ordenada conserva cinco apariciones y la lista de valores distintos solo tres; el tercer elemento contando repeticiones es 3, mientras el tercer valor distinto es 7. El significado de k depende de si contamos apariciones o valores únicos.'),coding('posicion','El tiempo k de entrenamiento',"Entrada: n y k (1 ≤ k ≤ n ≤ 100000), seguidos de n tiempos enteros entre 0 y 1000000000.\n\nSalida: el k-ésimo tiempo más pequeño, contando tiempos repetidos.",['Ordena sin borrar duplicados.','Accede a k − 1 después de ordenar.'],'El orden ascendente coloca exactamente los k − 1 elementos anteriores antes del elemento de índice k − 1. Por definición ese es el k-ésimo contando todas las apariciones. Los límites garantizan que el índice existe. Leemos y guardamos O(n) valores; ordenar requiere O(n log n) tiempo y la consulta final es constante.',cpp('    int n,k; cin >> n >> k;\n    vector<long long> a(n); for(auto &x:a) cin >> x;\n    sort(a.begin(),a.end());\n    cout << a[k-1] << "\\n";','iostream vector algorithm'),[['5 3\n7 3 7 1 3\n','3\n'],['1 1\n0\n','0\n'],['4 4\n9 2 5 2\n','9\n']])]),
'busqueda-exhaustiva':chapter('busqueda-exhaustiva',[
 ['Define exactamente una posibilidad',"Para elegir dos materiales distintos, representa una posibilidad por sus posiciones i y j. Usa i < j si el orden de elección no importa: cada pareja aparece una vez y nunca eliges la misma posición dos veces. Valores iguales en posiciones distintas siguen siendo materiales diferentes. Estas reglas definen qué candidatos deben recorrer los ciclos."],
 ['Separar generar, comprobar y mejorar',"Para cada pareja, calcula su costo, comprueba el presupuesto y, si es válida, compara con la mejor encontrada. Generar, comprobar y actualizar son tareas separadas. Si los costos son no negativos, mejor = −1 puede representar que aún no encontraste una pareja; cero no sirve como ausencia cuando una compra válida puede costar cero."],
 ['Por qué revisar todo demuestra el óptimo',"Toda pareja permitida tiene dos índices i < j y aparece en los ciclos, incluida una pareja óptima. Guardar la mejor válida asegura que al terminar no omites una solución superior. Este argumento necesita cobertura completa. Si revisas solo candidatos que parecen buenos, debes justificar por qué los demás no pueden mejorar la respuesta."],
 ['Verifica con un caso completamente enumerable',"Con [1,4,4] y presupuesto cinco, las parejas (0,1), (0,2) y (1,2) cuestan cinco, cinco y ocho. Las dos primeras sirven. Si piden el mejor costo, responde cinco; si piden cuántas parejas sirven, responde dos. La enumeración es la misma, pero debes cambiar qué acumulas y qué significa el estado final."],
 ['Usa los límites para decidir',"Hay n(n − 1)/2 parejas: 4950 para n = 100 y casi veinte mil millones para n = 200000. Usa esos límites para decidir si puedes enumerar. Para tamaños pequeños, la búsqueda completa ofrece una solución directa. También puede verificar otra más rápida comparando sus respuestas en entradas pequeñas con las mismas reglas."]
 ],[reasoning('cobertura','Enumera sin repetir','Para cuatro objetos A,B,C,D, escribe todas las parejas distintas sin importar el orden. Explica qué perderías si solo revisaras parejas vecinas en la lista.',['Cada pareja tiene un primer índice menor.','Vecinos no cubre, por ejemplo, A con D.'],'Las parejas son AB, AC, AD, BC, BD y CD. Revisar solo AB, BC y CD omite AC, AD y BD, cualquiera de las cuales podría ser óptima según sus costos. El hecho de que dos objetos no estén juntos en la entrada no los vuelve inválidos. La enumeración completa necesita visitar cada i < j.'),coding('presupuesto','Dos materiales para el club',"Entrada: n y b (2 ≤ n ≤ 200, 0 ≤ b ≤ 2000000000), seguidos de n precios entre 0 y 1000000000. Elige exactamente dos posiciones distintas.\n\nSalida: mayor suma que no supera b, o −1 si no existe pareja válida.",['Enumera i < j.','Actualiza la mejor suma solo si cabe en el presupuesto.'],'Los ciclos generan cada pareja de posiciones una vez. Para cada una calculamos la suma y, si no supera b, conservamos la mayor. Si ninguna es válida, el marcador −1 queda intacto. Precios repetidos son permitidos porque representan objetos distintos. El tiempo es O(n²) y la memoria O(n); con n ≤ 200 solo hay 19900 parejas.',cpp('    int n; long long b; cin >> n >> b;\n    vector<long long> a(n); for(auto &x:a) cin >> x;\n    long long mejor=-1;\n    for(int i=0;i<n;++i) for(int j=i+1;j<n;++j){\n        long long s=a[i]+a[j];\n        if(s<=b && s>mejor) mejor=s;\n    }\n    cout << mejor << "\\n";','iostream vector'),[['4 10\n2 6 5 9\n','8\n'],['2 3\n2 2\n','-1\n'],['3 0\n0 0 1\n','0\n'],['2 2000000000\n1000000000 1000000000\n','2000000000\n']])]),
'voraces':chapter('voraces',[
 ["Comprobar una regla para elegir monedas","Una regla voraz toma una decisión y continúa sin reconsiderarla. Para monedas 1, 5 y 10, elegir primero las mayores funciona; con 1, 3 y 4 falla para seis: 4 + 1 + 1 usa tres monedas y 3 + 3 usa dos. Antes de usar la regla, identifica qué propiedad de las denominaciones la hace válida."],
 ['Intercambia una solución sin empeorarla',"Con monedas 1, 5 y 10, cinco unos se cambian por un cinco usando menos monedas. Dos cincos se cambian por un diez. Por eso una solución óptima tiene menos de cinco unos y menos de dos cincos; el resto del valor está en dieces. Esa forma coincide con tomar tantos dieces y después tantos cincos como sea posible."],
 ['Del argumento a la operación',"Para veintiocho, toma dos dieces y conserva ocho pendientes; toma un cinco y quedan tres; termina con tres unos. Usas seis monedas. / cuenta cuántas de una denominación caben y % obtiene el pendiente. Son operaciones constantes, sin un ciclo por moneda. La prueba de intercambio es la que permite afirmar que ese total es mínimo."],
 ["Buscar un contraejemplo a otra regla","Prueba una regla nueva con ejemplos pequeños antes de implementarla. Para elegir actividades, la más corta, la que inicia primero y la de mayor premio pueden producir agendas distintas. Especifica qué quieres maximizar y qué restricciones cumples. Un contraejemplo descarta la regla; no encontrarlo en unas pruebas todavía no reemplaza una demostración."]
 ],[reasoning('contraejemplo','La moneda más grande puede fallar','Con monedas ilimitadas de 1,3 y 4, compara el método que toma siempre la mayor posible para cantidad 6 con una mejor solución. ¿Qué afirmación queda refutada?',['Después de tomar 4 quedan 2.','Dos monedas de 3 también suman 6.'],'El método voraz produce 4 + 1 + 1, tres monedas. La solución 3 + 3 usa dos y es mejor. Queda refutada la afirmación de que elegir siempre la moneda mayor minimiza el número para cualquier sistema de denominaciones. No refuta sistemas particulares que sí admiten una prueba; debemos revisar las propiedades de cada uno.'),coding('monedas','Cambio con unos, cincos y dieces',"Entrada: m (0 ≤ m ≤ 1000000000). Hay monedas ilimitadas de 1, 5 y 10.\n\nSalida: mínimo número de monedas para sumar exactamente m.",['Cuenta dieces y conserva el residuo.','Después cuenta cincos y finalmente unos.'],'Una solución óptima no contiene diez unos ni dos cincos cuando pueden convertirse en un diez con menos monedas. Tampoco contiene cinco unos, porque un cinco los reemplaza. Por tanto toma m / 10 dieces, después (m % 10) / 5 cincos y finalmente m % 5 unos. El argumento depende de estas denominaciones. Tiempo y memoria O(1).',cpp('    long long m; cin >> m;\n    cout << m/10 + (m%10)/5 + m%5 << "\\n";'),[['28\n','6\n'],['0\n','0\n'],['5\n','1\n'],['1000000000\n','100000000\n']])]),
'usaco-bronze-time-comp':chapter('usaco-bronze-time-comp',[
 ['No todos los ciclos anidados son iguales',"Para cada i de uno a n, visita sus múltiplos i, 2i, 3i y así hasta n. La cantidad interior es aproximadamente n/i, por lo que sumas n/1 + n/2 + ... + n/n. El total crece como O(n log n). Ver dos ciclos no basta para concluir O(n²): sus límites determinan cuántas vueltas hacen."],
 ['Agrupar ayuda a contar',"Agrupa índices en bloques que duplican tamaño: [1,2), [2,4), [4,8) y así. En [2^k,2^(k+1)), hay como máximo 2^k índices y cada uno aporta como máximo n/2^k visitas. El bloque aporta a lo sumo n. Como hay O(log n) bloques, la suma es O(n log n)."],
 ['Relaciona costo con el objetivo',"Imprimir todos los subconjuntos de n elementos exige visitar al menos 2ⁿ resultados. Contar cuántos hay solo requiere calcular una potencia. La salida decide parte del trabajo mínimo: no generes listas completas si solo necesitas su cantidad. Después de definir qué pide la tarea puedes buscar una representación que evite operaciones innecesarias."]
 ],[reasoning('sumatoria','Cuenta las visitas para cinco','Para n = 5, enumera los múltiplos visitados por i = 1,2,3,4,5. Suma las cantidades y explica por qué no hay 25 visitas.',['Para cada i, se visitan floor(n/i) números.','El salto del interior cambia con i.'],'Para i = 1 visitamos 1,2,3,4,5: cinco. Para 2, visitamos 2,4: dos. Para 3,4 y 5 visitamos uno cada vez. El total es 10. Los ciclos interiores no tienen todos longitud n; el salto i reduce sus vueltas. Contar 5 × 5 ignoraría esa dependencia.'),coding('visitas','Cuenta un recorrido de múltiplos',"Entrada: n (1 ≤ n ≤ 1000000). Para cada i entre 1 y n se visitarían i,2i,3i,... hasta n.\n\nSalida: total de visitas contando repeticiones entre diferentes i. Puedes sumar n / i sin ejecutar cada visita.",['Para un i fijo hay n / i múltiplos.','Suma esa cantidad para todos los i.'],'El múltiplo k × i cabe exactamente cuando k ≤ n/i. Por eso el ciclo interior tendría floor(n/i) vueltas. Sumarlas con un solo ciclo produce el mismo conteo sin visitar cada múltiplo. La implementación tarda O(n) y usa O(1) memoria, mientras la simulación directa cuesta O(n log n). Usamos long long para el total.',cpp('    int n; cin >> n;\n    long long total=0;\n    for(int i=1;i<=n;++i) total += n/i;\n    cout << total << "\\n";'),[['5\n','10\n'],['1\n','1\n'],['10\n','27\n']])]),
'usaco-bronze-intro-ds':chapter('usaco-bronze-intro-ds',[
 ['La estructura depende de las preguntas',"Si necesitas recuperar la tercera entrada, guarda posiciones en un vector y accede en O(1). Si necesitas cuántos sietes llegaron, usa frecuencias cuando el rango sea pequeño. Una pila entrega el último pendiente y una cola el primero. Elige según las consultas y cambios del problema; para una suma puede bastar un acumulador."],
 ['Valores como índices de una frecuencia',"Para valores entre cero y cien, crea 101 contadores. Con [7,2,7], aumenta frecuencia[7], luego frecuencia[2] y otra vez frecuencia[7]. Terminas con dos apariciones de siete y una de dos. Aquí el índice de la tabla representa un valor posible, no la posición que ese dato tenía en la entrada."],
 ['Tamaño, inicialización y empates',"vector<int> frecuencia(101,0) inicializa todos los contadores. Recorre los valores de menor a mayor y cambia el ganador solo ante una frecuencia mayor para conservar el menor en empates. Si los valores son muy grandes o negativos sin un rango pequeño, la tabla directa deja de servir; un diccionario o compresión permite representar las claves necesarias."]
 ],[reasoning('frecuencias','Posición y valor no son lo mismo','Para la entrada [4,1,4,2,1,4], escribe las frecuencias de 1,2 y 4. Explica qué significa frecuencia[4] y por qué no es lo mismo que el elemento de índice 4 de la lista original.',['La tabla usa valores posibles como posiciones.','La lista original cuenta desde índice cero.'],"Uno aparece dos veces, dos aparece una y cuatro aparece tres. Por eso frecuencia[4] vale tres. En la lista original, el índice cuatro contiene uno: es el quinto dato. El índice de la tabla representa un valor posible; el de la lista representa una posición de llegada."),coding('moda','Valor más frecuente',"Entrada: n (1 ≤ n ≤ 100000), seguido de n enteros entre 0 y 100.\n\nSalida: el valor más frecuente; en empate, el menor.",['Usa 101 contadores.','Recorre valores de menor a mayor y reemplaza el ganador solo con una frecuencia estrictamente mayor.'],'La tabla cuenta cada aparición en la posición del valor. Después recorremos 0 hasta 100. Cuando una frecuencia supera la del ganador lo actualizamos; al usar > y recorrer en orden, una igualdad conserva el valor menor. El tiempo es O(n + 101) y la memoria adicional O(101), independiente de la longitud de la lista.',cpp('    int n; cin >> n;\n    vector<int> f(101,0);\n    for(int i=0;i<n;++i){ int x; cin >> x; ++f[x]; }\n    int mejor=0;\n    for(int x=1;x<=100;++x) if(f[x]>f[mejor]) mejor=x;\n    cout << mejor << "\\n";','iostream vector'),[['6\n4 1 4 2 1 4\n','4\n'],['4\n7 2 7 2\n','2\n'],['1\n100\n','100\n'],['3\n0 0 1\n','0\n']])]),
'usaco-bronze-simulation':chapter('usaco-bronze-simulation',[
 ['Especifica cada transición',"Para simular una alcancía define el saldo inicial y la regla de cada evento. Un depósito suma; un retiro resta solo si hay fondos. Si falta dinero, este problema rechaza el retiro completo. Retirar parcialmente o permitir saldo negativo serían otras reglas y producirían otro historial. El estado debe guardar lo necesario para decidir el siguiente evento."],
 ['Una tabla revela el orden',"Con saldo diez, retirar siete deja tres; depositar dos deja cinco; retirar seis se rechaza y conserva cinco. Comprueba los fondos antes de restar para no tener que deshacer un cambio inválido. Si el problema describe cambios simultáneos, calcula el nuevo estado desde una copia del anterior; aquí los eventos sí ocurren en secuencia."],
 ['Demuestra el estado por pasos',"El saldo inicial es correcto por definición. Si el saldo antes de un evento es correcto y aplicas su regla, el siguiente también lo será. Repetir este argumento justifica toda la simulación. Con transición O(1), el tiempo es proporcional a los eventos. Si son demasiados, busca cómo agruparlos a partir de esa simulación ya definida."]
 ],[reasoning('orden','Retiros rechazados','Empieza con saldo 8. Procesa R 10, D 5, R 8, R 5, donde D deposita y R retira solo si alcanza. Escribe el saldo después de cada evento.',['Un retiro rechazado deja el saldo igual.','Cada comprobación usa el saldo actual.'],'Los saldos son 8, 13, 5 y 0. El primer retiro se rechaza porque 8 < 10. El depósito lleva a 13; retirar 8 deja 5 y retirar exactamente 5 es válido. Este caso prueba rechazo, depósito, retiro normal e igualdad, que suele distinguir >= de >.'),coding('alcancia','La alcancía del equipo',"Entrada: n y s (0 ≤ n ≤ 100000, 0 ≤ s ≤ 1000000000). Luego n líneas con D x o R x, donde 0 ≤ x ≤ 1000000000. D deposita x; R retira x solo si hay saldo suficiente y, si no, no cambia nada.\n\nSalida: saldo final.",['Mantén un único saldo de tipo long long.','Para R comprueba saldo >= x antes de restar.'],'Procesamos los eventos en orden. El saldo inicial es s; cada depósito suma y cada retiro permitido resta. Si un retiro no alcanza, el estado se conserva. Por inducción sobre eventos, el saldo siempre coincide con las reglas. La suma de depósitos puede superar int, así que usamos long long. Tiempo O(n), memoria adicional O(1).',cpp('    int n; long long saldo; cin >> n >> saldo;\n    for(int i=0;i<n;++i){\n        char tipo; long long x; cin >> tipo >> x;\n        if(tipo==\'D\') saldo+=x;\n        else if(saldo>=x) saldo-=x;\n    }\n    cout << saldo << "\\n";'),[['3 10\nR 7\nD 2\nR 6\n','5\n'],['0 0\n','0\n'],['4 8\nR 10\nD 5\nR 8\nR 5\n','0\n'],['2 1000000000\nD 1000000000\nD 1000000000\n','3000000000\n']])]),
'usaco-bronze-intro-complete':chapter('usaco-bronze-intro-complete',[
 ['Un espacio de búsqueda sin huecos',"Para elegir tres posiciones distintas sin importar el orden, exige i < j < k. Empieza j en i + 1 y k en j + 1. Cada terna de posiciones tiene un único orden creciente, así que la generas una vez. Los valores repetidos no invalidan la elección si ocupan posiciones distintas."],
 ['Comprueba restricciones después de generar',"Los límites de los ciclos garantizan índices diferentes; después puedes comprobar si sus valores suman el objetivo. Separar esa condición de la generación facilita revisar ambas partes. Para n = 4 hay cuatro ternas: escríbelas a mano y compara con el recorrido. Así puedes detectar tanto un candidato omitido como uno contado dos veces."],
 ['Cuenta antes de elegir el método',"Hay n(n − 1)(n − 2)/6 ternas. Con n = 100 son 161700; con n = 10000, el crecimiento cúbico hace la enumeración mucho mayor. Calcula la cantidad antes de elegir el método. Si necesitas otra solución, esta versión completa todavía puede comprobar sus resultados en casos pequeños."]
 ],[reasoning('ternas-por-posicion','¿Qué se está contando?',"En [1,1,1,1], cuenta las ternas de posiciones distintas que suman tres. Después cuenta las combinaciones de valores, permitiendo repetidos pero considerando iguales las que contienen los mismos tres valores. ¿Por qué cambian los resultados?",['Elige qué posición queda fuera.','Todas las ternas tienen los mismos valores.'],'Hay cuatro ternas de posiciones: cada una excluye una de las cuatro posiciones. Todas suman 3. Si contáramos combinaciones de valores sin distinguir posiciones, solo habría la combinación (1,1,1). La frase «posiciones distintas» define el objeto contado; eliminar valores repetidos cambiaría el problema.'),coding('ternas','Tres participantes suman el objetivo',"Entrada: n y t (3 ≤ n ≤ 100, −3000000000 ≤ t ≤ 3000000000), seguidos de n enteros entre −1000000000 y 1000000000.\n\nSalida: número de ternas de posiciones i < j < k cuya suma es t.",['Usa tres ciclos con comienzos crecientes.','Conserva las posiciones aunque sus valores coincidan.'],'Cada terna válida tiene una única ordenación creciente de índices, visitada por los ciclos. La comparación de suma la cuenta si y solo si alcanza t. No se generan índices iguales ni permutaciones repetidas. Usamos long long para sumas y objetivo. El tiempo es O(n³) y la memoria O(n); con cien datos hay 161700 ternas.',cpp('    int n; long long t; cin >> n >> t;\n    vector<long long>a(n);for(auto &x:a)cin>>x;\n    long long total=0;\n    for(int i=0;i<n;++i) for(int j=i+1;j<n;++j) for(int k=j+1;k<n;++k)\n        if(a[i]+a[j]+a[k]==t) ++total;\n    cout << total << "\\n";','iostream vector'),[['5 6\n1 2 3 4 5\n','1\n'],['4 3\n1 1 1 1\n','4\n'],['3 0\n-1 0 1\n','1\n'],['3 10\n1 2 3\n','0\n']])]),
'usaco-bronze-complete-rec':chapter('usaco-bronze-complete-rec',[
 ['Una decisión por posición',"Para formar un subconjunto, en cada posición i decide excluir o incluir su elemento y continúa en i + 1. Al llegar a i = n ya decidiste sobre todos: ese es el caso base y debe regresar. Cada rama representa una elección; seguir llamando desde el caso base intentaría consultar fuera de la lista."],
 ['Traza el árbol con dos elementos',"Con [2,5], las ramas producen vacío, solo cinco, solo dos y ambos, con sumas 0, 5, 2 y 7. Cada subconjunto tiene una secuencia única de decisiones. Para permutaciones necesitas otro árbol: elige un elemento todavía no usado para la siguiente posición y desmarca esa elección al regresar."],
 ['Estado y costo de regresar',"Si pasas la suma por valor, cada llamada recibe su propia copia. Si modificas una lista compartida, debes quitar el elemento al regresar antes de explorar otra rama. El árbol de subconjuntos tiene O(2ⁿ) nodos y profundidad n: tiempo O(2ⁿ) y memoria de llamadas O(n). Guardar todos los resultados exige memoria adicional."]
 ],[reasoning('arbol','Subconjuntos con repetidos','Dos posiciones contienen [3,3]. Enumera sus cuatro subconjuntos por posición y sus sumas. ¿Cuántos suman 3 y por qué no debes fusionar ambas posiciones?',['Cada posición tiene una decisión independiente.','Los valores iguales no identifican el mismo objeto.'],'Los subconjuntos son vacío, primera posición, segunda posición y ambas; sus sumas son 0,3,3 y 6. Dos suman 3. Aunque los valores coincidan, elegir la primera o la segunda posición representa decisiones diferentes. Si el problema pide subconjuntos de posiciones, deduplicar valores perdería respuestas legítimas.'),coding('subconjuntos','Subconjuntos con suma exacta',"Entrada: n y t (0 ≤ n ≤ 20, −20000000 ≤ t ≤ 20000000), seguidos de n enteros entre −1000000 y 1000000.\n\nSalida: cantidad de subconjuntos de posiciones cuya suma es t. Incluye el subconjunto vacío.",['En cada posición explora excluir e incluir.','Solo compara con t al llegar al caso base i == n.'],'La recursión toma una decisión binaria por posición. Cada subconjunto determina exactamente esas decisiones, así que aparece una vez. En la hoja contamos uno si la suma coincide. El subconjunto vacío es la rama que excluye todo y suma cero. Valores negativos impiden descartar simplemente sumas que ya superaron t. Tiempo O(2ⁿ), profundidad y memoria adicional O(n).','#include <iostream>\n#include <vector>\nusing namespace std;\nvector<long long> a; long long objetivo;\nlong long contar(int i,long long suma){\n    if(i==(int)a.size()) return suma==objetivo;\n    return contar(i+1,suma)+contar(i+1,suma+a[i]);\n}\nint main(){\n    int n;cin>>n>>objetivo;a.resize(n);for(auto &x:a)cin>>x;\n    cout<<contar(0,0)<<"\\n";\n}\n',[['3 3\n1 2 3\n','2\n'],['0 0\n','1\n'],['2 3\n3 3\n','2\n'],['2 0\n-1 1\n','2\n']])]),
'usaco-bronze-intro-sorting':chapter('usaco-bronze-intro-sorting',[
 ['Ordenar puede reemplazar comparaciones lejanas',"Sin ordenar, contar valores distintos podría requerir comparar cada dato con los anteriores: O(n²). Al ordenar, todas las apariciones iguales quedan juntas. Después basta recorrer y contar grupos. El costo pasa a O(n log n) por el ordenamiento más O(n) por el recorrido; la relación entre vecinos elimina las búsquedas repetidas."],
 ['Sigue los grupos en una traza',"[4,2,4,1,2,2] se ordena como [1,2,2,2,4,4]. El primer valor abre un grupo; el primer dos abre otro y el primer cuatro abre el tercero. Los demás continúan su grupo. Cada cambio entre vecinos marca un valor distinto. Si la lista está vacía no existe el primer grupo, así que el contador debe quedar en cero."],
 ['Conserva información cuando sea necesaria',"Ordenar cambia las posiciones originales. Si las necesitas para responder, guarda pares de valor e índice o elige otra estructura. Para varios campos, define una comparación estricta y desempates coherentes. El argumento sobre grupos supone que el ordenamiento es válido; un comparador que incumple sus condiciones puede invalidar el resultado."]
 ],[reasoning('grupos','Cuenta fronteras','Ordena [8,3,8,3,3,10] y señala cada posición donde inicia un valor distinto. Explica por qué el número de cambios entre vecinos es una unidad menor que el número de grupos en una lista no vacía.',['El primer grupo comienza sin una comparación anterior.','Cada cambio inicia exactamente otro grupo.'],'La lista es [3,3,3,8,8,10]. Los grupos comienzan en índices 0,3 y 5. Hay dos cambios entre vecinos, de 3 a 8 y de 8 a 10, pero tres grupos porque el primero ya existe al leer el primer elemento. Para una lista vacía la fórmula no se aplica sin un caso especial.'),coding('distintos','Valores distintos al ordenar',"Entrada: n (0 ≤ n ≤ 100000), seguido de n enteros entre −1000000000 y 1000000000.\n\nSalida: cantidad de valores distintos. Resuelve ordenando y comparando vecinos.",['Si n = 0, la respuesta es cero.','Para cada posición, cuenta si es la primera o difiere de la anterior.'],'Después de ordenar, todas las apariciones de un valor forman un bloque. Contamos el inicio de cada bloque: índice cero o valor distinto al anterior. Esto asigna una unidad a cada valor y ninguna a sus repeticiones. La condición i == 0 se evalúa primero y evita consultar a[−1]. Tiempo O(n log n), memoria para datos O(n).',cpp('    int n;cin>>n;vector<long long>a(n);for(auto &x:a)cin>>x;\n    sort(a.begin(),a.end());\n    int distintos=0;\n    for(int i=0;i<n;++i) if(i==0 || a[i]!=a[i-1]) ++distintos;\n    cout<<distintos<<"\\n";','iostream vector algorithm'),[['6\n4 2 4 1 2 2\n','3\n'],['0\n','0\n'],['4\n7 7 7 7\n','1\n'],['3\n-1 0 1\n','3\n']])]),
'usaco-bronze-intro-sets':chapter('usaco-bronze-intro-sets',[
 ['Conjunto y diccionario responden preguntas diferentes',"set guarda valores distintos: insertar dos veces el mismo no crea dos elementos. map guarda un dato asociado a cada clave, por ejemplo su frecuencia. Si necesitas saber cuántas veces llegó un número, set por sí solo pierde esa cantidad. Decide qué preguntas responderás antes de elegir uno de los dos."],
 ['Una consulta puede modificar un map',"En un map, frecuencia[x] crea la clave si no existía y le asigna un valor inicial. Eso permite contar con ++frecuencia[x], pero una consulta también puede modificar el contenedor. Para buscar sin insertar usa find. Si no encuentra la clave devuelve end; no lo trates como si señalara un elemento válido."],
 ['Orden y costo',"set y map ordenados permiten inserciones y búsquedas habituales en O(log n), y recorren las claves en orden. Las variantes unordered usan tablas hash y no conservan ese orden. Si el universo es pequeño, una tabla de frecuencias ofrece accesos O(1). El rango de las claves y las consultas determinan qué opción conviene."]
 ],[reasoning('eleccion','¿Set o map?','Debes responder dos preguntas sobre [5,2,5,8,2,5]: cuántos valores distintos hay y cuántas veces aparece cada valor. Explica qué almacena un set y qué añade un map de frecuencias.',['Un set conserva una sola copia por valor.','El dato asociado a la clave puede ser el contador.'],'El set contiene {2,5,8}, así que informa que hay tres valores distintos, pero no conserva las repeticiones. El map puede guardar 2→2, 5→3 y 8→1. Ambos ordenan claves, pero solo el segundo conserva las cantidades necesarias para responder frecuencias. La estructura debe mantener toda la información que las consultas requieren.'),coding('repeticiones','Avisos de matrícula repetida',"Entrada: n (0 ≤ n ≤ 100000), seguido de n identificadores enteros entre 0 y 1000000000.\n\nSalida: cuántas apariciones repiten un identificador visto anteriormente. Por ejemplo, tres apariciones del mismo identificador cuentan dos repeticiones.",['Guarda los identificadores ya vistos en un set.','Consulta antes de insertar o usa el resultado de insert.'],'Procesamos la secuencia en orden. Si un identificador ya pertenece al conjunto, su aparición es repetida; de lo contrario es la primera. Después lo insertamos para que las siguientes apariciones lo encuentren. Cada valor con frecuencia f contribuye f − 1. El tiempo es O(n log n) y la memoria O(n) en el peor caso.',cpp('    int n;cin>>n;set<long long> vistos;int repetidos=0;\n    for(int i=0;i<n;++i){\n        long long x;cin>>x;\n        if(vistos.find(x)!=vistos.end()) ++repetidos;\n        vistos.insert(x);\n    }\n    cout<<repetidos<<"\\n";','iostream set'),[['6\n5 2 5 8 2 5\n','3\n'],['0\n','0\n'],['3\n1 2 3\n','0\n'],['4\n7 7 7 7\n','3\n']])]),
'usaco-bronze-casework':chapter('usaco-bronze-casework',[
 ['Los casos deben cubrir todo sin contradicción',"Dos intervalos pueden estar separados, tocarse o compartir una longitud positiva. Dibuja un ejemplo de cada situación y decide qué respuesta corresponde. Las condiciones deben cubrir todas las entradas y coincidir en las fronteras. Si dos ramas pueden aplicarse a la misma entrada pero dan respuestas diferentes, todavía falta precisar los casos."],
 ['Una fórmula puede reunir los casos',"La parte común de [a,b] y [c,d] empieza en max(a,c) y termina en min(b,d). Su longitud es max(0, min(b,d) − max(a,c)). Si el final queda antes del inicio, no hay tramo común; si coinciden, hay contacto pero longitud cero. La misma fórmula cubre separación, contacto, contención y superposición."],
 ['No confundas longitud con puntos enteros',"Entre dos y cinco hay longitud tres, pero cuatro enteros: 2, 3, 4 y 5. Para contar posiciones enteras incluidas necesitas tratar los extremos de otra manera. Comprueba una intersección de un solo punto: su longitud es cero y su cantidad de puntos enteros puede ser uno. Especifica las unidades antes de elegir la fórmula."]
 ],[reasoning('fronteras','Longitud y cantidad','Los intervalos cerrados [1,4] y [4,7] se tocan en 4. ¿Cuál es la longitud de la intersección y cuántos puntos enteros contiene? Explica por qué no son la misma respuesta.',['Un solo punto no ocupa longitud positiva.','El punto 4 sí es un entero incluido.'],'La longitud es cero y la cantidad de puntos enteros es uno. La longitud mide distancia entre extremos; el conteo mide elementos discretos. Sumar uno a toda fórmula de intervalos sin preguntar qué se mide confunde ambos modelos. Este ejemplo de frontera obliga a precisar el significado de la salida.'),coding('intervalos','Tramo compartido',"Entrada: a,b,c,d (−1000000000 ≤ a ≤ b ≤ 1000000000 y lo mismo para c ≤ d). Representan dos segmentos cerrados.\n\nSalida: longitud de su intersección; si solo se tocan o no se cruzan, escribe 0.",['El inicio común es el mayor de los inicios.','El final común es el menor de los finales.'],'Un punto pertenece a ambos segmentos si está después de ambos inicios y antes de ambos finales. Por eso la parte común va de max(a,c) a min(b,d). Cuando el extremo final es menor o igual al inicial, la longitud es cero; en otro caso es su diferencia. long long evita desbordar al restar extremos lejanos. Tiempo y memoria O(1).',cpp('    long long a,b,c,d;cin>>a>>b>>c>>d;\n    long long inicio=max(a,c), fin=min(b,d);\n    cout<<max(0LL,fin-inicio)<<"\\n";','iostream algorithm'),[['1 7 4 10\n','3\n'],['1 4 4 7\n','0\n'],['1 2 5 6\n','0\n'],['-1000000000 1000000000 -1000000000 1000000000\n','2000000000\n']])]),
'usaco-bronze-intro-greedy':chapter('usaco-bronze-intro-greedy',[
 ["Elegir la actividad que termina antes","Para aceptar el máximo número de actividades en una sala, elige la que termina antes entre las compatibles. Deja libre la sala no después que cualquier otra elección y permite continuar con el mismo espacio futuro. El criterio es final más temprano; duración más corta o inicio más temprano no ofrecen por sí solos esa garantía."],
 ['Prueba de intercambio',"Toma una agenda óptima y sustituye su primera actividad por la compatible que termina antes. La nueva no termina después de la sustituida, así que siguen cabiendo las posteriores y conservas la cantidad. Tras fijarla, repite el argumento con las actividades que comiencen cuando la sala esté libre. Ese intercambio justifica cada decisión."],
 ['Las fronteras forman parte de la regla',"En este ejercicio una actividad puede empezar a la hora exacta en que termina otra: usa inicio >= últimoFinal. Si hubiera limpieza, habría que sumar ese tiempo a la disponibilidad. Ordena por final con desempates coherentes. Con duraciones positivas, empatar en final no altera el argumento, porque la disponibilidad posterior queda en el mismo instante."]
 ],[reasoning('criterio','La más corta no siempre basta','Hay actividades [0,3], [3,6] y [2,4]. Todas usan la misma sala. Si eliges primero la más corta, ¿cuántas puedes tomar? ¿Qué agenda obtiene más?',['La actividad [2,4] choca con las otras dos.','Dos intervalos que se tocan pueden coexistir aquí.'],'Elegir [2,4], de duración dos, impide tomar [0,3] y [3,6], por lo que deja solo una. La agenda [0,3] y [3,6] contiene dos. El ejemplo refuta elegir siempre la menor duración. Ordenar por final escoge [0,3] y conserva espacio para [3,6], alineando la decisión con la disponibilidad futura.'),coding('agenda','Una sala para muchos talleres',"Entrada: n (0 ≤ n ≤ 100000), seguido de n parejas inicio,fin con 0 ≤ inicio < fin ≤ 1000000000.\n\nSalida: máximo número de actividades sin superposición. Se permite que una empiece exactamente cuando otra termina.",['Ordena por hora de finalización.','Acepta una actividad si empieza después o al mismo tiempo que el último final elegido.'],'Ordenamos por final y recorremos. Si una actividad cabe, la aceptamos: sustituir la primera actividad de una agenda óptima por la que termina antes no elimina opciones posteriores. Aplicar ese intercambio repetidamente demuestra el máximo. Inicializamos la sala libre en tiempo cero, compatible con todos los inicios. El tiempo es O(n log n) y la memoria O(n).',cpp('    int n;cin>>n;vector<pair<long long,long long>> a;\n    for(int i=0;i<n;++i){long long s,e;cin>>s>>e;a.push_back({e,s});}\n    sort(a.begin(),a.end());\n    long long libre=0;int total=0;\n    for(auto p:a) if(p.second>=libre){++total;libre=p.first;}\n    cout<<total<<"\\n";','iostream vector algorithm utility'),[['3\n0 3\n3 6\n2 4\n','2\n'],['0\n','0\n'],['3\n0 10\n1 2\n2 3\n','2\n'],['3\n1 5\n2 5\n3 5\n','1\n']])]),
'usaco-bronze-intro-graphs':chapter('usaco-bronze-intro-graphs',[
 ['Define qué representa una conexión',"En un grafo, los vértices representan objetos y las aristas sus relaciones. Una amistad mutua se guarda en ambos sentidos; una calle de un solo sentido requiere dirección. El dibujo ayuda a ver conexiones, pero la lista de relaciones define el grafo. Los vértices pueden ser personas, salones o estados de un problema."],
 ['Lista de adyacencia y grado',"vector<vector<int>> vecinos(n) crea una lista por vértice. Para la arista no dirigida u–v, añade v a vecinos[u] y u a vecinos[v]. En un grafo simple, la longitud de la lista es su grado. Cada arista aporta dos a la suma de grados, así que esta debe valer 2m; úsalo para comprobar la construcción."],
 ['Presencia de una arista no es alcanzabilidad',"A y C pueden estar conectados por A–B–C sin tener una arista directa. El grado cuenta vecinos inmediatos; no cuenta todos los vértices alcanzables. BFS y DFS permiten explorar esa segunda relación. Antes de recorrer, revisa índices, dirección y si se permiten lazos o aristas repetidas: esas condiciones cambian la representación o su interpretación."]
 ],[reasoning('grados-y-aristas','Comprueba un grafo pequeño','Hay vértices 1,2,3,4 y aristas no dirigidas 1–2, 2–3 y 2–4. Escribe el grado de cada vértice, suma los grados y explica por qué el resultado duplica el número de aristas.',['Cada arista toca dos extremos.','El vértice 2 conecta con los otros tres.'],'Los grados son 1,3,1 y 1; suman 6. Hay tres aristas y cada una se cuenta una vez en cada extremo, así que la suma es 2 × 3. El grado de 1 es uno aunque pueda llegar a otros vértices pasando por 2: grado y alcanzabilidad describen propiedades distintas.'),coding('grados','Conexiones del campus',"Entrada: n,m (1 ≤ n ≤ 100000, 0 ≤ m ≤ 100000), luego m aristas u,v con 1 ≤ u,v ≤ n y u ≠ v. No hay aristas repetidas. El grafo es no dirigido.\n\nSalida: los grados de los vértices 1..n en una línea.",['Cada arista aumenta dos contadores.','Puedes guardar solo grados si no necesitas recorrer caminos.'],'Inicializamos un contador por vértice. Para cada arista incrementamos ambos extremos, porque pertenece a los dos. Al terminar, cada contador incluye exactamente las aristas incidentes a ese vértice. No necesitamos listas completas para esta consulta, aunque serían útiles para explorar vecinos. Tiempo O(n + m), memoria O(n).',cpp('    int n,m;cin>>n>>m;vector<int> grado(n,0);\n    for(int i=0;i<m;++i){int u,v;cin>>u>>v;++grado[u-1];++grado[v-1];}\n    for(int i=0;i<n;++i){if(i)cout<<" ";cout<<grado[i];}\n    cout<<"\\n";','iostream vector'),[['4 3\n1 2\n2 3\n2 4\n','1 3 1 1\n'],['1 0\n','0\n'],['3 1\n1 3\n','1 0 1\n']])]),
'usaco-bronze-rect-geo':chapter('usaco-bronze-rect-geo',[
 ['Representa un rectángulo con intervalos',"Un rectángulo paralelo a los ejes queda descrito por x1, y1, x2, y2, con extremos ordenados. El ancho es x2 − x1 y el alto y2 − y1; multiplicarlos da el área. Funciona con coordenadas negativas: usamos diferencias entre extremos. No hace falta recorrer los puntos del plano para medir la superficie."],
 ['La intersección ocurre en ambos ejes',"La intersección necesita un tramo común positivo en ambos ejes. El ancho es max(0, min(x2A,x2B) − max(x1A,x1B)); calcula el alto de la misma forma con y. Multiplica ambas longitudes. Si solo comparten un borde o un punto, alguna dimensión vale cero y también el área común."],
 ['Traza ambas dimensiones',"A va de (0,0) a (5,4) y B de (2,1) a (7,3). Comparten x desde dos hasta cinco, ancho tres, y y desde uno hasta tres, alto dos. El área común es seis. Si mueves B por encima de y = 4, el alto común se vuelve cero aunque todavía se crucen horizontalmente."],
 ['Área cubierta y tamaño de las cuentas',"Para el área de la unión calcula áreaA + áreaB − intersección: la suma inicial contó dos veces la zona común. No es el área del rectángulo mínimo que los contiene, que puede incluir zonas vacías. Usa long long antes de multiplicar diferencias. Las fórmulas tienen costo constante incluso con coordenadas grandes."]
 ],[reasoning('union','No confundas cobertura con envolvente','Los rectángulos son [0,0] a [2,2] y [4,0] a [6,2]. Calcula el área cubierta por ambos y el área del rectángulo mínimo que los contiene. Explica la diferencia.',['Hay un espacio horizontal sin cubrir.','La unión no rellena automáticamente el hueco.'],"Cada rectángulo tiene área cuatro y están separados, así que la unión tiene área ocho. El rectángulo que los contiene va de x = 0 a 6 y de y = 0 a 2: área doce. Las cuatro unidades cuadradas del hueco entre x = 2 y x = 4 pertenecen a esa envolvente, pero no a la región cubierta."),coding('interseccion','Área común de dos patios',"Entrada: ocho enteros x1,y1,x2,y2,x3,y3,x4,y4, cada uno entre −1000000000 y 1000000000. Se garantiza x1 ≤ x2, y1 ≤ y2, x3 ≤ x4, y3 ≤ y4.\n\nSalida: área de intersección de ambos rectángulos paralelos a los ejes.",['Calcula la intersección de los intervalos de x y de y.','Trunca las dimensiones negativas a cero y multiplica como long long.'],"Calcula el tramo común en x y en y con máximo de inicios y mínimo de finales. Reemplaza longitudes negativas por cero y multiplica ambas. Un punto pertenece a la intersección solo cuando cumple las dos condiciones, así que esa región es un rectángulo, posiblemente sin área. Cada dimensión mide hasta 2000000000 y su producto, 4000000000000000000, cabe en long long. Tiempo y memoria O(1).",cpp('    long long a,b,c,d,e,f,g,h;cin>>a>>b>>c>>d>>e>>f>>g>>h;\n    long long ancho=max(0LL,min(c,g)-max(a,e));\n    long long alto=max(0LL,min(d,h)-max(b,f));\n    cout<<ancho*alto<<"\\n";','iostream algorithm'),[['0 0 5 4 2 1 7 3\n','6\n'],['0 0 2 2 2 0 4 2\n','0\n'],['0 0 1 1 3 3 4 4\n','0\n'],['-1000000000 -1000000000 1000000000 1000000000 -1000000000 -1000000000 1000000000 1000000000\n','4000000000000000000\n']])]),
'usaco-bronze-ad-hoc':chapter('usaco-bronze-ad-hoc',[
 ['Busca qué no cambia',"Sumar dos conserva la paridad de un número; mover una ficha entre cajas conserva el total. Una propiedad que no cambia se llama invariante. Puede demostrar que un objetivo es imposible sin simular. Busca la propiedad en ejemplos pequeños y después comprueba que cada operación permitida la conserva, no solo las que elegiste en la muestra."],
 ['Necesario no siempre es suficiente',"Una condición necesaria no demuestra por sí sola que el objetivo pueda alcanzarse. Para ir de cero a x en k pasos de una unidad, necesitas |x| ≤ k y que k − |x| sea par. Ambas bastan: recorre |x| pasos hacia el destino y usa los restantes en parejas de ida y vuelta. La construcción completa la justificación."],
 ['De observar ejemplos a una prueba',"Para x = 2 y k = 4, avanza dos veces y añade una pareja derecha-izquierda. Para k = 3, esa pareja no cabe y la paridad impide terminar en dos. Los ejemplos sugieren la condición; la cuenta y la construcción la demuestran para cualquier entrada. En un problema ad hoc, esa observación sale de las operaciones concretas."]
 ],[reasoning('necesarias','Distancia y paridad','Desde 0 debes llegar a 3 usando exactamente 6 pasos de +1 o −1. La distancia cabe en seis pasos, pero ¿es posible? Explica qué propiedad falta revisar.',['Cada paso cambia la paridad de la posición.','Tras un número par de pasos terminas en una posición par.'],'No es posible. Aunque 3 ≤ 6, después de seis cambios de paridad la posición final debe ser par, mientras 3 es impar. Equivalentemente, 6 − 3 es impar y no puede gastarse en parejas de ida y vuelta. Revisar solo distancia detecta una condición necesaria, pero no suficiente.'),coding('pasos','Entrenator en la recta',"Entrada: x y k (−1000000000 ≤ x ≤ 1000000000, 0 ≤ k ≤ 1000000000). Entrenator parte de 0 y cada paso cambia su posición en +1 o −1.\n\nSalida: SI si puede terminar en x después de exactamente k pasos, o NO en otro caso.",['La distancia mínima es |x|.','Los pasos sobrantes deben poder agruparse en pares de ida y vuelta.'],'Se necesitan al menos |x| pasos, así que si k es menor no alcanza. Al tomar |x| pasos hacia el objetivo, cualquier par adicional puede ser una ida y vuelta que no cambia el final. Por ello basta y es necesario que k − |x| sea par. La necesidad de paridad también se ve porque cada paso cambia la paridad de la posición. Tiempo y memoria O(1).',cpp('    long long x,k;cin>>x>>k;\n    long long distancia=x<0?-x:x;\n    cout<<((k>=distancia && (k-distancia)%2==0)?"SI":"NO")<<"\\n";'),[['2 4\n','SI\n'],['3 6\n','NO\n'],['0 0\n','SI\n'],['-5 3\n','NO\n'],['-5 7\n','SI\n']])]),
'usaco-bronze-bronze-conclusion':chapter('usaco-bronze-bronze-conclusion',[
 ["Elegir el método según los límites","Ante un problema mezclado, empieza por la entrada, los límites y ejemplos pequeños. Una búsqueda completa puede bastar con n pequeño; una tabla de frecuencias puede ayudar con un rango corto. Elige entre simular, enumerar, ordenar o contar según las operaciones necesarias y justifica su costo. El título del tema no debe decidir el método."],
 ["Revisar representación, costo y fronteras","Antes de dar una solución por terminada, comprueba su representación, una traza, la razón de corrección, el costo y las fronteras. Una pieza ausente indica qué revisar. Después de estudiar una solución, reconstruye el argumento y pregunta qué condición lo haría fallar. Por ejemplo, permitir negativos puede invalidar una poda válida con positivos."],
 ['Un ejercicio que combina decisiones',"Para encontrar los dos tiempos más cercanos, comparar todas las parejas funciona en O(n²). Si ordenas, basta revisar vecinos: entre dos valores separados hay diferencias vecinas no negativas cuya suma es su diferencia. Alguna no puede ser mayor que ese total. Por eso descartar las parejas no vecinas conserva una respuesta mínima."]
 ],[reasoning('seleccion','Elige herramientas con límites','Un problema pide contar valores distintos. En una versión n ≤ 30; en otra n ≤ 200000; en otra todos los valores están entre 0 y 50. Propón métodos y explica por qué los límites influyen.',['Enumerar comparaciones puede bastar para treinta.','Un universo pequeño permite contadores directos.'],'Para treinta datos podemos comparar cada valor con los anteriores en O(n²), con una prueba de no contar duplicados. Para doscientos mil, ordenar y contar cambios o usar un conjunto evita el costo cuadrático. Si el universo es 0..50, una tabla de presencia de 51 posiciones da tiempo O(n + 51). No hay una estructura única ideal para todas las restricciones.'),coding('cercanos','Los tiempos más cercanos',"Entrada: n (2 ≤ n ≤ 100000), seguido de n tiempos entre 0 y 1000000000.\n\nSalida: menor diferencia absoluta entre tiempos de dos posiciones distintas. Los tiempos repetidos son válidos y producen diferencia cero.",['Ordena los tiempos.','Basta comparar vecinos en el orden.'],"Ordena y calcula las diferencias entre vecinos. La diferencia entre dos posiciones separadas es la suma de las diferencias vecinas intermedias, todas no negativas. Por eso no puede ser menor que todas ellas: alguna pareja vecina alcanza un mínimo. Conserva la menor diferencia, incluida cero si hay repetidos. Ordenar cuesta O(n log n), recorrer O(n) y almacenar O(n).",cpp('    int n;cin>>n;vector<long long>a(n);for(auto &x:a)cin>>x;\n    sort(a.begin(),a.end());\n    long long mejor=a[1]-a[0];\n    for(int i=2;i<n;++i) mejor=min(mejor,a[i]-a[i-1]);\n    cout<<mejor<<"\\n";','iostream vector algorithm'),[['5\n12 5 20 9 30\n','3\n'],['2\n0 1000000000\n','1000000000\n'],['4\n7 2 7 15\n','0\n']])]),
};
